DROP TABLE IF EXISTS t_mapportkeybiz_6 CASCADE;

CREATE TABLE t_mapportkeybiz_6 (
   cbussinessid int DEFAULT 0,
   cneid int NOT NULL DEFAULT 0,
   cboardid int NOT NULL DEFAULT 0,
   cportkey varchar(255)
)
tablespace unmdb_space
distributed masteronly
;


CREATE INDEX ix_mapportkeybiz_6 ON t_mapportkeybiz_6 (
cbussinessid ASC
);

DROP TABLE IF EXISTS t_restlog CASCADE;

CREATE TABLE t_restlog (
   cseqno bigserial,
   cregisterno int,
   cserialno int,
   caccesstoken varchar(64),
   cclientip char(32),
   cclientport int,
   cusername varchar(32),
   curi varchar(255),
   cmethod varchar(16),
   cbegintime timestamp,
   cendtime timestamp,
   cretcode int,
   cclientiphash bigint,
   cmethodhash bigint,
   cusernamehash bigint,
   creservedint int,
   creserved char(1),
   CONSTRAINT pk_restlog_seqno PRIMARY KEY (cseqno)
)
tablespace unmdb_space
distributed by (cseqno)
;


CREATE INDEX ix_restlog_time ON t_restlog (
cbegintime ASC
);


CREATE INDEX ix_restlog_clientiphash ON t_restlog (
cclientiphash ASC
);


CREATE INDEX ix_restlog_usernamehash ON t_restlog (
cusernamehash ASC
);


CREATE INDEX ix_restlog_methodhash ON t_restlog (
cmethodhash ASC
);


CREATE INDEX ix_restlog_clientip ON t_restlog (
cclientip ASC
);


CREATE INDEX ix_restlog_username ON t_restlog (
cusername ASC
);


CREATE INDEX ix_restlog_method ON t_restlog (
cmethod ASC
);

